create extension if not exists pgcrypto;
create table if not exists public.franchise_packages (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, investment_amount numeric(12,2) not null check(investment_amount>=0), description text not null default '', promotional_offer text not null default '', terms text not null default '', is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_package_items (id uuid primary key default gen_random_uuid(), package_id uuid not null references public.franchise_packages(id) on delete cascade, category text not null, name text not null, quantity numeric, unit text, dimensions text, unit_price numeric(12,2), is_included boolean not null default true, needs_confirmation boolean not null default false, confirmation_note text, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_benefits (id uuid primary key default gen_random_uuid(), package_id uuid references public.franchise_packages(id) on delete cascade, benefit_type text not null default 'general' check(benefit_type in ('general','training','marketing','promotion')), title text not null, description text not null default '', is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_locations (id uuid primary key default gen_random_uuid(), franchise_name text not null, city text not null, address text not null, contact_name text, contact_phone text, status text not null default 'planned' check(status in ('planned','active','inactive')), image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_enquiries (id uuid primary key default gen_random_uuid(), full_name text not null, mobile text not null, email text, city text not null, package_id uuid references public.franchise_packages(id) on delete set null, preferred_budget text, message text not null default '', status text not null default 'new' check(status in ('new','contacted','in_progress','converted','closed')), internal_notes text not null default '', source_ip_hash text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_images (id uuid primary key default gen_random_uuid(), package_id uuid references public.franchise_packages(id) on delete set null, storage_path text unique not null, public_url text not null, caption text not null default '', alt_text text not null default '', is_published boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.franchise_faqs (id uuid primary key default gen_random_uuid(), question text not null, answer text not null, is_published boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(), brand_name text not null default 'Chai Rides', tagline text not null default 'Ride to Sip', location text not null default 'Siddipet, Telangana, India', phone text not null default '+91 6302567570', whatsapp_message text not null default '', hero_heading text not null default '', hero_text text not null default '', about_heading text not null default '', about_content text not null default '', terms text not null default '', updated_at timestamptz not null default now());
create index if not exists idx_items_package_sort on public.franchise_package_items(package_id,sort_order);
create index if not exists idx_enquiries_created on public.franchise_enquiries(created_at desc);
create index if not exists idx_enquiries_status on public.franchise_enquiries(status);
create index if not exists idx_images_package on public.franchise_images(package_id,sort_order);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['franchise_packages','franchise_package_items','franchise_benefits','franchise_locations','franchise_enquiries','franchise_images','franchise_faqs','site_settings'] loop execute format('drop trigger if exists set_updated_at on public.%I',t); execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t); end loop; end $$;
alter table public.franchise_packages enable row level security; alter table public.franchise_package_items enable row level security; alter table public.franchise_benefits enable row level security; alter table public.franchise_locations enable row level security; alter table public.franchise_enquiries enable row level security; alter table public.franchise_images enable row level security; alter table public.franchise_faqs enable row level security; alter table public.site_settings enable row level security;
create policy "public active packages" on public.franchise_packages for select using(is_active);
create policy "public included package items" on public.franchise_package_items for select using(is_included and exists(select 1 from public.franchise_packages p where p.id=package_id and p.is_active));
create policy "public active benefits" on public.franchise_benefits for select using(is_active and (package_id is null or exists(select 1 from public.franchise_packages p where p.id=package_id and p.is_active)));
create policy "public published images" on public.franchise_images for select using(is_published);
create policy "public published faqs" on public.franchise_faqs for select using(is_published);
create policy "public site settings" on public.site_settings for select using(true);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('franchise-images','franchise-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
create policy "public franchise image read" on storage.objects for select using(bucket_id='franchise-images');
